// A focused report; existing retry/next/select handlers own navigation.
let reportBadgesBefore=new Set(),reportPreviousTier='',reportAnnounced=false;
const reportWords={ko:['이번 주행 메달','보유 최고 메달','금메달','은메달','동메달','다음 목표','초 단축하면','최고 등급 달성','새 배지 획득','재도전','스테이지 선택','FLIGHT COMPLETE','FLIGHT ENDED'],en:['THIS RUN','BEST MEDAL','Gold','Silver','Bronze','Next target','s faster for','Highest medal earned','NEW BADGES','Retry','Select stage','FLIGHT COMPLETE','FLIGHT ENDED'],ja:['今回のメダル','最高メダル','金','銀','銅','次の目標','秒短縮で','最高ランク獲得','新バッジ','リトライ','ステージ選択','FLIGHT COMPLETE','FLIGHT ENDED'],zh:['本次奖牌','最佳奖牌','金牌','银牌','铜牌','下一目标','秒即可获得','已达最高等级','获得新徽章','重试','选择关卡','FLIGHT COMPLETE','FLIGHT ENDED']};
function reportTierAt(seconds,index){const target=medalTargetFor(index);return seconds<=target.gold+1e-7?'gold':seconds<=target.silver+1e-7?'silver':'bronze'}
function reportMedalSVG(tier){const colors={gold:['#ffe9ac','#c69c4d','#6a4826'],silver:['#e3f4ff','#91aebe','#455f77'],bronze:['#f3c599','#b58159','#634333']}[tier];return '<svg viewBox="0 0 100 112" aria-hidden="true"><defs><linearGradient id="reportMedalTone" x2=".7" y2="1"><stop stop-color="'+colors[0]+'"/><stop offset=".5" stop-color="'+colors[1]+'"/><stop offset="1" stop-color="'+colors[2]+'"/></linearGradient></defs><path d="M22 4h22l12 38-18 9z" fill="#375b78"/><path d="M56 4h22L62 51 44 42z" fill="#6b8da4"/><circle cx="50" cy="71" r="34" fill="'+colors[2]+'"/><circle cx="50" cy="68" r="34" fill="url(#reportMedalTone)" stroke="'+colors[0]+'"/><circle cx="50" cy="68" r="27" fill="none" stroke="'+colors[2]+'" stroke-width="2"/><path d="m50 46 6 14 16 2-12 10 4 16-14-9-14 9 4-16-12-10 16-2z" fill="'+colors[0]+'" stroke="'+colors[2]+'"/></svg>'}
function medalImprovementGap(seconds,target){return (Math.ceil(Math.max(0,seconds-target-1e-7)*100)/100).toFixed(2);}
function updateFlightReport(){if(editorTesting||creatorActive||!['win','dead'].includes(state))return;const w=reportWords[settings.language]||reportWords.ko,win=state==='win'&&mode==='story';$('overlay').setAttribute('data-report','true');$('eyebrow').textContent=win?w[11]:w[12];$('reportMedal').classList.toggle('hidden',!win);$('reportTarget').classList.toggle('hidden',!win);if(win){const tier=reportTierAt(time,level),rank={gold:2,silver:3,bronze:4},best=medalTier(level);$('reportMedalIcon').innerHTML=reportMedalSVG(tier);$('reportMedalLabel').textContent=w[0];$('reportMedalName').textContent=w[rank[tier]];$('reportMedalBest').textContent=w[1]+' · '+w[rank[best]];const target=medalTargetFor(level),next=tier==='bronze'?'silver':'gold';$('reportTarget').textContent=tier==='gold'?w[7]:w[5]+' · '+w[rank[next]]+' · '+formatMedalRequirement(target[next])+' · '+({ko:medalImprovementGap(time,target[next])+'초 단축하면 '+w[rank[next]],en:'Improve by '+medalImprovementGap(time,target[next])+' s for '+w[rank[next]],ja:medalImprovementGap(time,target[next])+'秒短縮で'+w[rank[next]],zh:'缩短'+medalImprovementGap(time,target[next])+'秒可获'+w[rank[next]]}[settings.language]);$('completionRetry').textContent=w[9];$('home').textContent=w[10];$('medalResult').classList.add('hidden');}
 const fresh=BADGE_DEFS.filter(d=>data.badges.unlocked[d.id]&&!reportBadgesBefore.has(d.id));$('reportNewBadges').textContent=fresh.length?w[8]+' · '+fresh.map(d=>tr(d.name)).join(' / '):'';$('reportNewBadges').classList.toggle('hidden',!fresh.length);
 if(!reportAnnounced){reportAnnounced=true;const upgrade=win&&['','bronze','silver','gold'].indexOf(medalTier(level))>['','bronze','silver','gold'].indexOf(reportPreviousTier);$('overlay').setAttribute('data-report-highlight',String(!!(upgrade||fresh.length||storyCompletion?.fresh)));if((upgrade||fresh.length)&&settings.sound)beep(1050,.12,'sine');}
}
const reportBegin=beginRun;beginRun=function(...args){reportBadgesBefore=new Set(Object.keys(data.badges.unlocked));reportPreviousTier=mode==='story'?medalTier(level):'';reportAnnounced=false;$('overlay').setAttribute('data-report','false');for(const id of ['reportMedal','reportTarget','reportNewBadges'])$(id).classList.add('hidden');return reportBegin(...args)};
const reportFinish=finish;finish=function(...args){const out=reportFinish(...args);updateFlightReport();return out};result=finish;
const reportFailureFeedback=showFailureFeedback;showFailureFeedback=function(...args){const out=reportFailureFeedback(...args);if(state==='dead'&&!reportAnnounced)updateFlightReport();return out};
const reportMenu=showMenu;showMenu=function(...args){$('overlay').setAttribute('data-report','false');for(const id of ['reportMedal','reportTarget','reportNewBadges'])$(id).classList.add('hidden');return reportMenu(...args)};
